--
-- Table structure for table `product_import_runs`
--

DROP TABLE IF EXISTS `product_import_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_import_runs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `run_number` int(10) unsigned NOT NULL,
  `import_type` enum('full','partial') NOT NULL DEFAULT 'full',
  `source_file` varchar(255) DEFAULT NULL,
  `uploaded_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `total_products_uploaded` int(10) unsigned DEFAULT 0,
  `products_inserted` int(10) unsigned DEFAULT 0,
  `products_updated` int(10) unsigned DEFAULT 0,
  `products_deleted` int(10) unsigned DEFAULT 0,
  `validation_errors` int(10) unsigned DEFAULT 0,
  `status` enum('pending','processing','completed','failed','cancelled') NOT NULL DEFAULT 'pending',
  `error_message` longtext DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `run_number` (`run_number`),
  KEY `idx_run_number` (`run_number`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_status` (`status`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tracks all product import operations for version control and restore functionality';
/*!40101 SET character_set_client = @saved_cs_client */;

