--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(180) NOT NULL,
  `slug` varchar(220) NOT NULL,
  `short_description` varchar(280) NOT NULL,
  `long_description` text NOT NULL,
  `flavour_notes` text DEFAULT NULL,
  `texture_notes` text DEFAULT NULL,
  `ingredients_summary` text DEFAULT NULL,
  `packaging_note` text DEFAULT NULL,
  `topper_note` text DEFAULT NULL,
  `sku` varchar(80) NOT NULL,
  `collection_category_id` bigint(20) unsigned NOT NULL,
  `subcategory_id` bigint(20) unsigned DEFAULT NULL,
  `child_category_id` bigint(20) unsigned DEFAULT NULL,
  `occasion_tag` varchar(100) DEFAULT NULL,
  `dietary_tag` enum('regular','eggless','vegan','sugar_free') NOT NULL DEFAULT 'regular',
  `is_veg` tinyint(1) NOT NULL DEFAULT 1,
  `is_eggless` tinyint(1) NOT NULL DEFAULT 0,
  `is_vegan` tinyint(1) NOT NULL DEFAULT 0,
  `availability_status` enum('in_stock','out_of_stock','preorder','draft') NOT NULL DEFAULT 'in_stock',
  `lead_time_hours` int(11) NOT NULL DEFAULT 24,
  `customisation_note` text DEFAULT NULL,
  `delivery_eligible` tinyint(1) NOT NULL DEFAULT 1,
  `pickup_eligible` tinyint(1) NOT NULL DEFAULT 1,
  `featured_image` varchar(255) DEFAULT NULL,
  `starting_price` decimal(10,2) NOT NULL,
  `base_price` decimal(10,2) NOT NULL,
  `discount_price` decimal(10,2) DEFAULT NULL,
  `stock_quantity` int(11) NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_bestseller` tinyint(1) NOT NULL DEFAULT 0,
  `is_chef_special` tinyint(1) NOT NULL DEFAULT 0,
  `seo_title` varchar(190) DEFAULT NULL,
  `seo_description` varchar(260) DEFAULT NULL,
  `rating_average` decimal(3,2) NOT NULL DEFAULT 0.00,
  `review_count` int(11) NOT NULL DEFAULT 0,
  `is_b2b_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `b2b_minimum_quantity` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  `topper_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1 = allow topper selection on PDP',
  `note_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1 = show Note on the Cake input on PDP, 0 = hide it',
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  UNIQUE KEY `sku` (`sku`),
  KEY `idx_products_slug` (`slug`),
  KEY `idx_products_sku` (`sku`),
  KEY `idx_products_collection` (`collection_category_id`),
  KEY `idx_products_subcategory` (`subcategory_id`),
  KEY `idx_products_child_category` (`child_category_id`),
  KEY `idx_products_occasion` (`occasion_tag`),
  KEY `idx_products_dietary` (`dietary_tag`),
  KEY `idx_products_is_veg` (`is_veg`),
  KEY `idx_products_is_eggless` (`is_eggless`),
  KEY `idx_products_is_vegan` (`is_vegan`),
  KEY `idx_products_active_filter` (`availability_status`,`deleted_at`,`collection_category_id`),
  KEY `idx_products_featured` (`is_featured`),
  KEY `idx_products_bestseller` (`is_bestseller`),
  KEY `idx_products_category_status` (`collection_category_id`,`availability_status`,`deleted_at`),
  KEY `idx_products_slug_status` (`slug`,`availability_status`,`deleted_at`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`collection_category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`subcategory_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `products_ibfk_3` FOREIGN KEY (`child_category_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=245 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
